.ptr{display:inline-flex;align-items:center;gap:10px;padding:8px 14px;border-radius:999px;background:#fafafa;border:1px solid #d4d4d4;font:500 14px system-ui,sans-serif}
.ptr__s{width:18px;height:18px;border:2px solid #d4d4d4;border-top-color:#0a0a0a;border-radius:50%;animation:ptrs .8s linear infinite}
@keyframes ptrs{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.ptr__s{animation-duration:2s}}
